<?php require __DIR__.'/bootstrap.php'; $products=read_json('products.json',[]); $id=(string)($_GET['id']??''); $p=null; foreach($products as $item) if(($item['id']??'')===$id&& !empty($item['available'])){$p=$item;break;} if(!$p){http_response_code(404);site_header('Cake not found');echo '<section class="content"><div class="empty-state"><h2>Cake not found</h2><a class="button" href="cakes.php">Back to cakes</a></div></section>';site_footer();exit;} site_header($p['name']); ?>
<section class="content"><div class="product-detail"><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><div><div class="eyebrow"><?= e($p['category']) ?></div><h1><?= e($p['name']) ?></h1><p class="description"><?= e($p['description']) ?></p><div class="price" data-live-price><?= money((float)$p['price']) ?></div><p class="muted">Choose your options below. A custom message is required for every cake.</p><form action="cart.php" method="post" class="card-panel"><input type="hidden" name="action" value="add"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= e($p['id']) ?>"><div class="field"><label for="size">Size / serving option *</label><select id="size" name="size" required data-size-select><?php foreach(($p['sizes']??[['label'=>'Standard','price'=>$p['price']]]) as $s): ?><option value="<?= e($s['label']) ?>" data-price="<?= (float)$s['price'] ?>"><?= e($s['label']) ?> — <?= money((float)$s['price']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="flavour">Flavour *</label><select id="flavour" name="flavour" required data-flavour-select><?php foreach(($p['flavours']??[['label'=>'Standard','extra'=>0]]) as $f): ?><option value="<?= e($f['label']) ?>" data-extra="<?= (float)$f['extra'] ?>"><?= e($f['label']) ?><?= ($f['extra']??0)>0?' (+'.money((float)$f['extra']).')':'' ?></option><?php endforeach; ?></select></div><div class="field"><label for="qty">Quantity *</label><input id="qty" name="qty" type="number" min="1" max="20" value="1" required></div><div class="field"><label for="custom_message">Custom message <span class="required">*</span></label><input id="custom_message" name="custom_message" required maxlength="180" placeholder="e.g. Happy Birthday, Aisha!"></div><div class="field"><label for="occasion">Occasion (optional)</label><input id="occasion" name="occasion" placeholder="e.g. Birthday, wedding, anniversary"></div><div class="field"><label for="instructions">Special instructions (optional)</label><textarea id="instructions" name="instructions" placeholder="e.g. Pink and white decorations"></textarea></div><div class="field"><label for="additional">Additional requests (optional)</label><input id="additional" name="additional" placeholder="e.g. Add a small chocolate topper"></div><button class="button" type="submit" style="width:100%">Add to cart ↗</button><p class="muted">Need a one-of-a-kind design? <a class="text-link" href="custom-cake.php">Request a custom cake</a>.</p></form></div></div></section><?php site_footer(); ?>
